// Write the account email: an invite, a password reset, or another sign-in
// email. The link must lead into this project's own sign-in, so even someone
// holding the key cannot send a client a link of their own.
const LINK = 'https://ruducnccpiasyhcebzcv.supabase.co/auth/v1/verify?';
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const b = $input.first().json.body || {};
const to = String(b.to || '').trim();
if (!/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/.test(to)) throw new Error('No valid address to send to.');
const kind = String(b.kind || '');
const link = String(b.link || '');
if (kind !== 'code' && !link.startsWith(LINK)) throw new Error('Not a link into the FTG portal.');
const first = esc(String(b.name || '').trim().split(/\s+/)[0]) || 'there';

const button = text => '<p style="margin:24px 0"><a href="' + esc(link) + '" style="display:inline-block;background:#E8B923;color:#2C2320;padding:12px 24px;border-radius:10px;font-weight:700;text-decoration:none">' + text + '</a></p>';
const sign = '<p>Thank you,<br>Finance Therapy Group</p>';
const expired = 'The link works once, for a limited time. If it has expired, go to <a href="' + APP + '">financetherapygroup.netlify.app</a>, press <b>Sign In</b>, then <b>Forgot Password?</b>, for a new one.';

const EMAILS = {
  invite: ['Your Finance Therapy Group portal is ready',
    '<p>Hi ' + first + ',</p><p>Your Finance Therapy Group client portal is ready. It is where you send us documents, see what we need from you each month, and read your reports.</p>' + button('Set your password') + '<p>' + expired + '</p>'],
  reset: ['Reset your Finance Therapy Group password',
    '<p>Hi ' + first + ',</p><p>We got a request to reset the password for your Finance Therapy Group portal.</p>' + button('Choose a new password') + '<p>' + expired + ' If you did not ask for this, you can ignore this email: your password stays the same.</p>'],
  magiclink: ['Your Finance Therapy Group sign-in link',
    '<p>Hi ' + first + ',</p><p>Here is your link to sign in to the Finance Therapy Group portal.</p>' + button('Sign in') + '<p>' + expired + '</p>'],
  signup: ['Confirm your email for Finance Therapy Group',
    '<p>Hi ' + first + ',</p><p>Please confirm your email address for the Finance Therapy Group portal.</p>' + button('Confirm my email') + '<p>' + expired + '</p>'],
  email_change: ['Confirm your new email for Finance Therapy Group',
    '<p>Hi ' + first + ',</p><p>Please confirm this new email address for your Finance Therapy Group portal.</p>' + button('Confirm my new email') + '<p>' + expired + '</p>'],
  code: ['Your Finance Therapy Group code',
    '<p>Hi ' + first + ',</p><p>Your code is <b style="font-size:20px;letter-spacing:3px">' + esc(b.code) + '</b>. It works once, for a limited time.</p>'],
};
const email = EMAILS[kind];
if (!email) throw new Error('No email called "' + kind + '".');
return [{ json: { to, subject: email[0], html: email[1] + sign } }];
